# Proteins (cuprot): lessons.
LESSONS = {
"meat-structure": LES([
 P("Why is a tenderloin tender and a shank tough? The answer is in how much each muscle worked, and it decides how you cook it."),
 K("Meat is muscle: bundles of long <b>fibers</b> (protein), held together by <b>connective tissue</b> (mainly collagen, plus tough elastin, called silverskin), with <b>fat</b> between and inside the muscles (marbling). Muscles that work hard (shoulder, leg, shank) have more connective tissue: cook them with <b>slow, moist heat</b>. Muscles that do little (loin, rib, tenderloin) are tender: cook them with <b>quick, dry heat</b>."),
 TB(["Cut", "Worked", "Best method"], [["Beef tenderloin", "Little", "Roast, grill, sauté"], ["Beef chuck (shoulder)", "Hard", "Braise, stew"], ["Pork loin", "Little", "Roast, grill"], ["Pork shoulder", "Hard", "Braise, slow roast"], ["Lamb rack", "Little", "Roast"], ["Lamb shank", "Hard", "Braise"]]),
 W("<b>Slice across the grain.</b> The grain is the direction the fibers run. Cutting across it leaves short fibers that are easy to chew; cutting along it leaves long, stringy ones. This matters most for cuts like flank and brisket."),
 EX("Method", "You have beef short ribs, from a hard-working area full of connective tissue.", ["Lots of collagen needs time and moist heat to become gelatin."], "Braise them."),
 M("Grilling a tough cut fast and serving it in thick slices along the grain."),
 DRILL("Look closely at a flank steak and find the grain. Cook it, slice half with the grain and half across, and taste both."),
 SCI([("/biology/high-school-biology/proteins/", "Proteins", "what heat does to protein (denaturing)"), ("/biology/life-science/muscular-system/", "Muscles", "how muscle is built")]),
 TRY,
], "cia", "g_primal"),

"primal-cuts": LES([
 P("Butchers break a carcass down in stages: first into large <b>primal cuts</b>, then into <b>subprimals</b>, then into the steaks, chops and roasts you buy."),
 K("<b>Beef primals (U.S.):</b> chuck, rib, short loin, sirloin, round, brisket, plate, flank (plus the shank). <b>Pork primals:</b> shoulder (Boston butt and picnic), loin, belly (side), leg (ham). <b>Lamb primals:</b> shoulder, rack (rib), loin, leg, plus breast and shank."),
 TB(["Beef primal", "Where", "Known cuts"], [
   ["Chuck", "Shoulder", "Chuck roast, ground chuck, short ribs (some)"],
   ["Rib", "Upper back, ribs 6 to 12", "Rib roast (prime rib), ribeye"],
   ["Short loin", "Middle back", "Strip steak, T-bone, porterhouse, tenderloin"],
   ["Sirloin", "Hip, in front of the round", "Sirloin steaks, tri-tip"],
   ["Round", "Rear leg", "Top round, bottom round, eye of round"],
   ["Brisket", "Lower chest", "Brisket"],
   ["Plate", "Belly, below the rib", "Skirt steak, short ribs"],
   ["Flank", "Belly, below the loin", "Flank steak"],
 ], "The U.S. beef primals"),
 W("Knowing where a cut comes from tells you how it will behave. The rib and short loin ride along the back and work little: tender, expensive steaks. The chuck, round and brisket do the walking: tougher, cheaper, wonderful braised."),
 EX("Which primal?", "A T-bone steak (a strip and a piece of tenderloin on a T-shaped bone).", ["Both the strip and the tenderloin lie in the short loin."], "The short loin."),
 M("Thinking brisket and chuck can be grilled like a ribeye. They are hard-working cuts that need long, slow cooking."),
 DRILL("At a meat counter, find one cut from each of five beef primals and note the price per pound. Which are cheapest, and why?"),
 MP([("guides/differences/#ground-beef", "Ground beef: 80/20, 85/15, 90/10", "what the numbers mean"), ("recipes/delmonico-steak/", "Delmonico Steak", "a cut from the short loin or rib")]),
 TRY,
], "g_primal", "cia"),

"brines": LES([
 P("A pork chop brined for a few hours comes out juicier and seasoned all the way through. Salt does that."),
 K("A <b>brine</b> is salt dissolved in water, measured <b>by weight</b>: a 5% brine is 50 g of salt per 1,000 g (1 liter) of water. Salt moves into the meat and changes its proteins so they hold more water. A <b>dry brine</b> is salt rubbed on the surface and left to sit, refrigerated. A <b>marinade</b> (oil, acid, flavorings) mostly flavors the surface. A <b>rub</b> is a dry spice mix."),
 LI("Brine and marinate in the refrigerator, in a food-safe container.",
    "Weigh the salt: different salts measure very differently by the spoon.",
    "Rinse or pat dry after brining, or the surface won't brown.",
    "Don't reuse a raw marinade as a sauce unless you boil it first; better, set some aside before it touches raw meat."),
 W("Strong acid in a long marinade can turn the surface mushy rather than tender. Most marinades work in hours, not days."),
 EX("Mix a brine", "How much salt for 3 liters (3,000 g) of 6% brine?", ["$3000 \\times 0.06 = 180$ g."], "180 g of salt."),
 EX("Percent", "You dissolved 75 g of salt in 1,500 g of water. What percent brine is that?", ["$75 \\div 1500 = 0.05 = 5\\%$."], "5%."),
 M("Measuring brine salt with a cup. A cup of fine table salt weighs much more than a cup of flaky kosher salt."),
 DRILL("Dry-brine one chicken breast with about 1% of its weight in salt overnight in the refrigerator, and cook it beside an unbrined one. Compare juiciness and seasoning."),
 MP([("guides/differences/#salt", "Table, kosher and sea salt", "why salt must be weighed")]),
 TRY,
], "g_brine", "foodcode"),

"poultry": LES([
 P("Buying whole chickens and breaking them down is cheaper and gives you bones for stock. It takes about five minutes once you know where the joints are."),
 K("<b>The eight-piece cut:</b> two drumsticks, two thighs, two wings, two breast halves (often cut in half again). Find the joints with your fingers and cut through them, not through bone: bend the leg out until the hip joint pops, cut around it; separate drumstick from thigh at the knee joint (follow the fat line); cut the wings off at the shoulder; cut the breast away from the ribs along the breastbone. Save the back and frame for stock."),
 LI("Work on a board set aside for raw poultry, on a tray if you can.",
    "Use a sharp boning or chef's knife; the tip finds joints.",
    "<b>Airline breast:</b> a boneless breast with the first wing bone left on.",
    "<b>Spatchcock:</b> cut out the backbone with shears and press the bird flat so it roasts evenly and fast."),
 SAFE("Don't rinse raw poultry in the sink; USDA advises against it because water splashes germs around the kitchen. Cooking to 165°F kills them.", "Wash hands, board, knife and the sink area after; then clean and sanitize."),
 W("Dark meat (legs and thighs) has more connective tissue and fat than breast, so it tolerates higher temperatures and longer cooking. Many cooks cook thighs past 165°F, to 175°F or more, for tenderness; the breast dries out above about 165°F."),
 EX("Yield", "A 4 lb chicken gives 2.8 lb of pieces after you remove the back and trim. What is the yield percent?", ["$2.8 \\div 4 = 0.70$."], "70%."),
 M("Sawing through bone at the hip. Bend the joint until it pops and cut through the gap."),
 DRILL("Break down a whole chicken into eight pieces. Time yourself. Do it once a week for a month; note your time each week.", "Make stock from the backs and wing tips you saved."),
 MP([("guides/differences/#chicken-cuts", "Chicken breasts vs. thighs", "how they cook differently"), ("scratch/chicken-stock/", "Chicken stock", "use the frame")]),
 TRY,
], "usda_temps", "cia"),

"fish": LES([
 P("Fish is delicate and spoils fast, so buying well matters as much as cooking well."),
 K("<b>Freshness signs:</b> a clean smell like the sea (not fishy), firm flesh that springs back, bright clear eyes (not cloudy or sunken), red or pink gills, shiny skin, and fillets without gaps or browning. Keep fish very cold, on ice in the refrigerator, and use it soon. <b>Round fish</b> (salmon, trout, snapper) give two fillets; <b>flatfish</b> (sole, flounder) give four."),
 LI("Scale and gut if needed; rinse and dry.",
    "Lay the fish on its side. Cut behind the head down to the backbone.",
    "Turn the knife toward the tail and cut along the backbone with long, smooth strokes, keeping the blade against the bones.",
    "Lift the fillet away; turn the fish over and repeat.",
    "Trim the belly bones; pull the pin bones with fish tweezers, in the direction they point."),
 W("Fish muscle has very little connective tissue, so it cooks quickly and falls apart if overcooked. Fish is done at 145°F, or when the flesh turns opaque and flakes."),
 EX("Yield", "A 3 lb whole salmon gives 1.35 lb of skinless fillet. Yield percent?", ["$1.35 \\div 3 = 0.45$."], "45%."),
 M("Pressing the knife into the bones and leaving flesh on the frame. Let the blade ride on the bones."),
 DRILL("Buy a whole trout or small snapper and fillet it. Weigh the fish before and the fillets after, and work out your yield.", "Cook the frame into a quick fish fumet (30 minutes)."),
 MP([("recipes/fish-bonne-femme/", "Fish Bonne Femme", "classic poached fish with mushrooms")]),
 TRY,
], "usda_temps", "cia"),

"shellfish": LES([
 P("Shellfish includes <b>crustaceans</b> (shrimp, lobster, crab) and <b>mollusks</b> (clams, mussels, oysters, scallops, squid). Live shellfish must stay alive until cooking."),
 K("<b>Live clams, mussels and oysters:</b> shells closed, or they close when tapped; throw away any with cracked shells or that stay open. Store them cold (about 41°F or below) in a container that breathes, covered with a damp towel, never sealed airtight and never in fresh water. Restaurants keep the <b>shellstock tag</b> that comes with each container for <b>90 days</b> after it is emptied, as the Food Code requires, so an outbreak can be traced."),
 LI("Cook clams, mussels and oysters until their shells open; discard any that stay shut.",
    "Shrimp, lobster and crab are done when the flesh is pearly and opaque.",
    "Debeard mussels just before cooking (pull the fibers toward the hinge).",
    "Crustacean shellfish is one of the nine major allergens; mollusks are a separate group."),
 W("A live mollusk keeps its shell closed with a muscle. A dead one can't, and it may already be spoiling. The tag tells inspectors where and when the shellfish was harvested."),
 EX("Keep or toss?", "A mussel is open and doesn't close when you tap it.", ["It is probably dead."], "Throw it away."),
 SAFE("Raw or undercooked shellfish carries a higher risk; restaurants that serve raw oysters must post a consumer advisory under the Food Code."),
 M("Storing live shellfish in a sealed plastic bag or in a bowl of tap water; both kill them."),
 DRILL("Buy a pound of mussels. Sort them (tap test), debeard them, and steam them with white wine and shallots until they open, about 4 to 6 minutes."),
 MP([("recipes/lobster-newberg/", "Lobster Newberg", "Delmonico's famous lobster dish")]),
 TRY,
], "foodcode", "usda_temps"),

"doneness": LES([
 P("Take a roast out of the oven and its center keeps getting hotter for a while. Cooks plan for that rise; it's called <b>carryover cooking</b>."),
 K("<b>Carryover:</b> the hot outer layers keep pushing heat inward after the meat leaves the heat, so the center rises a few degrees for a steak and often 5°F to 10°F or more for a large roast. <b>Pull</b> meat a little before the temperature you want, and <b>rest</b> it, loosely covered, before slicing."),
 V("cu-carry", {"mode": "carry"}, "Change the roast's size and the oven temperature, then see how far the center rises after you pull it."),
 TB(["Chef's doneness term", "Center (after rest), about"], [["Rare", "120°F to 125°F"], ["Medium-rare", "130°F to 135°F"], ["Medium", "135°F to 145°F"], ["Medium-well", "145°F to 155°F"], ["Well done", "155°F and up"]], "Doneness words cooks use. USDA's safe minimum for whole cuts of beef, pork, veal and lamb is 145°F with a 3-minute rest."),
 W("Rare and medium-rare steaks are below USDA's 145°F. In restaurants, the Food Code allows whole, intact steaks to be served that way when the outside is cooked, and requires a consumer advisory on the menu for undercooked animal foods. At home, cooks make their own choice; for ground meat and poultry, the safe temperatures are firm."),
 EX("When to pull", "You want a roast at 135°F after resting and expect a 7°F rise. When do you take it out?", ["$135 - 7 = 128$."], "At about 128°F."),
 M("Slicing as soon as it leaves the oven. The center hasn't finished cooking, and juices run onto the board."),
 DRILL("Roast a pork loin. Pull it at 138°F, leave the probe in, and write down the reading every 2 minutes for 15 minutes. How much did it rise?"),
 MP([("guides/food-safety/#temperatures", "Safe minimum internal temperatures", "the USDA table")]),
 TRY,
], "g_carry", "usda_temps", "foodcode"),

"eggs": LES([
 P("Chefs have long tested new cooks with an omelet. It looks simple and shows everything: heat control, timing, pan work and patience."),
 K("<b>French omelet:</b> beaten eggs stirred fast in a buttered pan over medium heat until soft curds form, then rolled into a smooth, pale cylinder, creamy inside, with no brown. <b>American omelet:</b> cooked flatter, filled, folded in half, often lightly browned. <b>Poached egg:</b> cracked into barely simmering water (about 180°F) with a splash of vinegar, cooked about 3 to 4 minutes until the white is set and the yolk soft."),
 LI("Use a small nonstick or well-seasoned pan, about 8 inches for 2 to 3 eggs.",
    "French omelet: stir with a fork or spatula while shaking the pan; stop when it is like loose scrambled eggs; let it set a few seconds; roll it out onto the plate.",
    "Poaching: very fresh eggs hold together best; crack each into a small cup first, then slide it in.",
    "Hold poached eggs in ice water and rewarm in hot water for service."),
 SAFE("USDA: cook eggs until the yolk and white are firm, and egg dishes to 160°F. Soft yolks and runny omelets are a choice many diners make; for children, older adults, pregnant people and anyone with a weak immune system, pasteurized eggs are the safer pick."),
 W("Egg proteins set at fairly low temperatures, the white at about 145°F to 150°F and the yolk a little higher. High heat overshoots, squeezing out water so eggs turn rubbery and weep."),
 EX("Which omelet?", "Pale yellow, no browning, rolled into a cylinder, soft inside.", ["That is the classic French style."], "A French omelet."),
 M("High heat. A French omelet should never brown."),
 DRILL("Make six French omelets in a row, two eggs each. Eat the good ones; feed the rest to the family as scrambled eggs.", "Poach four eggs, holding them in ice water, then rewarm them all at once."),
 MP([("recipes/eggs-benedict/", "Eggs Benedict", "poached eggs and hollandaise, from Delmonico's"), ("guides/food-safety/", "Food Safety Basics", "eggs and egg dishes")]),
 TRY,
], "g_omelette", "usda_temps"),
}
